insert into public.questions (exam_category, subject, topic, type, difficulty, body, body_hi, question_data, options, marks_correct, marks_wrong, explanation, explanation_hi, concept_group_id, source_type, source_citation, status)
values
('upsc','Geography','World Regions, Water Bodies & Places','mcq','easy','When it is 12 noon at Greenwich (0° longitude), what is the local time at a place on 75° E longitude?','जब ग्रीनविच (0° देशांतर) पर दोपहर के 12 बजे हों, तब 75° पूर्वी देशांतर पर स्थित किसी स्थान का स्थानीय समय क्या होगा?','{"craft": "application"}'::jsonb,'[{"id": "a", "body": "7 a.m.", "body_hi": "सुबह 7 बजे", "isCorrect": false}, {"id": "b", "body": "5 a.m.", "body_hi": "सुबह 5 बजे", "isCorrect": false}, {"id": "c", "body": "7 p.m.", "body_hi": "शाम 7 बजे", "isCorrect": false}, {"id": "d", "body": "5 p.m.", "body_hi": "शाम 5 बजे", "isCorrect": true}]'::jsonb,2,0.66,'The Earth rotates through 360 degrees in 24 hours, that is, 15 degrees an hour or one degree every four minutes. A place 75 degrees east of Greenwich sees the Sun 75 x 4 = 300 minutes, or five hours, earlier, so its local time is ahead: 5 p.m. Places to the east of Greenwich are ahead of Greenwich time and places to the west are behind it, which is why the world is divided into time zones.','पृथ्वी 24 घंटे में 360 अंश घूमती है, यानी 15 अंश प्रति घंटा या हर चार मिनट में एक अंश। ग्रीनविच से 75 अंश पूर्व का स्थान सूर्य को 75 x 4 = 300 मिनट, यानी पाँच घंटे, पहले देखता है, इसलिए उसका स्थानीय समय आगे है: शाम 5 बजे। ग्रीनविच के पूर्व के स्थान ग्रीनविच समय से आगे और पश्चिम के स्थान पीछे होते हैं, इसीलिए विश्व को समय-क्षेत्रों में बाँटा गया है।','l1-geo-longitude-local-time-75e','original_pattern_matched','NCERT Class VI, Geography -- The Earth: Our Habitat (Globe: Latitudes and Longitudes).','draft'),
('upsc','Geography','World Regions, Water Bodies & Places','statement_based','easy','Consider the following statements about the heat zones of the Earth:','पृथ्वी के ताप कटिबंधों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Torrid Zone lies between the Tropic of Cancer and the Tropic of Capricorn, and receives the most heat.", "The Temperate Zones lie between the Tropics and the Arctic and Antarctic Circles.", "The Frigid Zones lie between the Equator and the Tropics."], "statements_hi": ["उष्ण कटिबंध कर्क रेखा और मकर रेखा के बीच स्थित है, और सबसे अधिक ऊष्मा पाता है।", "शीतोष्ण कटिबंध उष्ण कटिबंधीय रेखाओं और आर्कटिक तथा अंटार्कटिक वृत्तों के बीच स्थित हैं।", "शीत कटिबंध विषुवत रेखा और उष्ण कटिबंधीय रेखाओं के बीच स्थित हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: the mid-day Sun is exactly overhead at least once a year on every latitude in the Torrid Zone, while in the Temperate Zones it never shines overhead, and its rays fall at ever smaller angles towards the poles, so temperatures are moderate. Statement 3 is wrong: the Frigid Zones lie between the Arctic Circle and the North Pole and between the Antarctic Circle and the South Pole, where the Sun does not rise much above the horizon and it is very cold.','कथन 1 और 2 सही हैं: उष्ण कटिबंध के हर अक्षांश पर वर्ष में कम से कम एक बार दोपहर का सूर्य ठीक सिर के ऊपर होता है, जबकि शीतोष्ण कटिबंधों में वह कभी सिर के ऊपर नहीं चमकता, और ध्रुवों की ओर उसकी किरणें छोटे से छोटे कोण पर पड़ती हैं, इसलिए तापमान मध्यम रहता है। कथन 3 गलत है: शीत कटिबंध आर्कटिक वृत्त और उत्तरी ध्रुव के बीच, तथा अंटार्कटिक वृत्त और दक्षिणी ध्रुव के बीच स्थित हैं, जहाँ सूर्य क्षितिज से अधिक ऊपर नहीं उठता और बहुत ठंड होती है।','l1-geo-heat-zones','original_pattern_matched','NCERT Class VI, Geography -- The Earth: Our Habitat (Globe: Latitudes and Longitudes).','draft'),
('upsc','Geography','World Regions, Water Bodies & Places','statement_based','easy','Consider the following statements about plateaus:','पठारों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The African plateau is famous for gold and diamond mining.", "The Tibet plateau is the lowest plateau in the world."], "statements_hi": ["अफ़्रीकी पठार सोने और हीरे के खनन के लिए प्रसिद्ध है।", "तिब्बत का पठार विश्व का सबसे निचला पठार है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "recall"}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: plateaus are very useful because they are rich in mineral deposits -- the African plateau for gold and diamonds, and the Chhotanagpur plateau in India for huge reserves of iron, coal and manganese. Statement 2 is wrong: the Tibet plateau, rising 4,000 to 6,000 metres above mean sea level, is the highest plateau in the world.','केवल कथन 1 सही है: पठार बहुत उपयोगी हैं क्योंकि वे खनिज भंडारों से समृद्ध होते हैं -- अफ़्रीकी पठार सोने और हीरे के लिए, और भारत का छोटानागपुर पठार लोहे, कोयले और मैंगनीज़ के विशाल भंडारों के लिए। कथन 2 गलत है: औसत समुद्र तल से 4,000 से 6,000 मीटर ऊँचा तिब्बत का पठार विश्व का सबसे ऊँचा पठार है।','l1-geo-african-plateau-tibet-height','original_pattern_matched','NCERT Class VI, Geography -- The Earth: Our Habitat (Major Landforms of the Earth).','draft'),
('upsc','Geography','World Regions, Water Bodies & Places','statement_based','easy','Consider the following statements about maps:','मानचित्रों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["A small-scale map, such as one in an atlas, shows a large area in less detail.", "On maps, blue is generally used for water bodies and brown for mountains.", "A plan is a drawing of a small area on a large scale."], "statements_hi": ["छोटे पैमाने का मानचित्र, जैसे एटलस का, बड़े क्षेत्र को कम विवरण के साथ दिखाता है।", "मानचित्रों पर सामान्यतः जलाशयों के लिए नीला और पर्वतों के लिए भूरा रंग प्रयुक्त होता है।", "योजना (plan) किसी छोटे क्षेत्र का बड़े पैमाने पर बनाया गया रेखाचित्र है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. Small-scale maps show large areas such as continents or countries, while large-scale maps show small areas, such as a village or a town, in great detail. Colours and conventional symbols make maps easy to read -- blue for water, brown for mountains, yellow for plateaus and green for plains -- and a sketch, unlike a map or a plan, is drawn from memory without a scale.','तीनों कथन सही हैं। छोटे पैमाने के मानचित्र महाद्वीपों या देशों जैसे बड़े क्षेत्र दिखाते हैं, जबकि बड़े पैमाने के मानचित्र गाँव या नगर जैसे छोटे क्षेत्र बहुत विस्तार से दिखाते हैं। रंग और रूढ़ चिह्न मानचित्रों को पढ़ने में आसान बनाते हैं -- जल के लिए नीला, पर्वतों के लिए भूरा, पठारों के लिए पीला और मैदानों के लिए हरा -- और रेखाचित्र (sketch), मानचित्र या योजना के विपरीत, बिना पैमाने के स्मृति से बनाया जाता है।','l1-geo-map-scale-colours-plan','original_pattern_matched','NCERT Class VI, Geography -- The Earth: Our Habitat (Maps).','draft'),
('upsc','Geography','World Regions, Water Bodies & Places','assertion_reason','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "Oases in the Sahara are found in valleys and shallow depressions.", "assertion_hi": "सहारा में मरूद्यान (oases) घाटियों और उथले गर्तों में मिलते हैं।", "reason": "In such low places, underground water reaches the surface.", "reason_hi": "ऐसे निचले स्थानों में भूमिगत जल सतह तक पहुँच जाता है।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true, "craft": "inference"}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": true}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct, and Statement-II explains Statement-I. Where underground water comes to the surface, an oasis forms; people settle there and grow date palms and crops, and the oases have long been stopping points on the caravan routes across the desert. Away from the oases, the Sahara is not only sand: besides the sandy desert there are gravel plains and high plateaus with bare, rocky surfaces.','दोनों कथन सही हैं, और कथन-II कथन-I की व्याख्या करता है। जहाँ भूमिगत जल सतह पर आ जाता है, वहाँ मरूद्यान बनता है; लोग वहाँ बसकर खजूर और फ़सलें उगाते हैं, और मरूद्यान लंबे समय से मरुस्थल पार करने वाले कारवाँ मार्गों के पड़ाव रहे हैं। मरूद्यानों से दूर, सहारा केवल रेत नहीं है: रेतीले मरुस्थल के अलावा वहाँ बजरी के मैदान और नंगी, चट्टानी सतह वाले ऊँचे पठार भी हैं।','l1-geo-sahara-oases-depressions','original_pattern_matched','NCERT Class VII, Geography -- Our Environment (Life in the Deserts).','draft'),
('upsc','Geography','World Regions, Water Bodies & Places','mcq','medium','Some people of the Amazon basin live in large apartment-like houses with steeply slanting roofs. These are called','अमेज़न बेसिन के कुछ लोग तीखी ढलवाँ छतों वाले बड़े, अपार्टमेंट जैसे घरों में रहते हैं। ये क्या कहलाते हैं?','{"craft": "precision"}'::jsonb,'[{"id": "a", "body": "igloos", "body_hi": "इग्लू", "isCorrect": false}, {"id": "b", "body": "chalets", "body_hi": "शैले (chalet)", "isCorrect": false}, {"id": "c", "body": "kraals", "body_hi": "क्राल (kraal)", "isCorrect": false}, {"id": "d", "body": "malocas", "body_hi": "मलोका (maloca)", "isCorrect": true}]'::jsonb,2,0.66,'In the Amazon basin, people live in thatched houses shaped like beehives, and some in large apartment-like houses called malocas, with steeply slanting roofs that shed the heavy rain. Igloos are the snow houses once built by the Inuit in winter, chalets are the wooden houses of the Alps, and kraals are the cattle enclosures and homesteads of herding peoples in southern Africa.','अमेज़न बेसिन में लोग मधुमक्खी के छत्ते जैसे आकार के छप्पर वाले घरों में रहते हैं, और कुछ मलोका कहलाने वाले बड़े, अपार्टमेंट जैसे घरों में, जिनकी तीखी ढलवाँ छतें भारी वर्षा का पानी बहा देती हैं। इग्लू इनुइट द्वारा सर्दियों में बनाए जाने वाले हिम-घर थे, शैले आल्प्स के लकड़ी के घर हैं, और क्राल दक्षिणी अफ़्रीका के पशुपालक लोगों के बाड़े और घर हैं।','l1-geo-amazon-maloca-houses','original_pattern_matched','NCERT Class VII, Geography -- Our Environment (Life in the Tropical and Subtropical Region).','draft'),
('upsc','Geography','World Regions, Water Bodies & Places','mcq','medium','The Ural mountains form the traditional boundary between','यूराल पर्वत परंपरागत रूप से किनके बीच की सीमा बनाते हैं?','{"craft": "recall"}'::jsonb,'[{"id": "a", "body": "Europe and Asia", "body_hi": "यूरोप और एशिया", "isCorrect": true}, {"id": "b", "body": "Asia and Africa", "body_hi": "एशिया और अफ़्रीका", "isCorrect": false}, {"id": "c", "body": "Europe and Africa", "body_hi": "यूरोप और अफ़्रीका", "isCorrect": false}, {"id": "d", "body": "North America and Asia", "body_hi": "उत्तरी अमेरिका और एशिया", "isCorrect": false}]'::jsonb,2,0.66,'Europe and Asia form one great landmass, Eurasia, and the Ural mountains are taken as the line between them. Europe lies to the west of Asia, with the Arctic Ocean to its north and the Atlantic to its west. Asia is separated from Africa by the Red Sea and the Suez region, and from North America by the narrow strait between Siberia and Alaska.','यूरोप और एशिया मिलकर एक विशाल भूभाग, यूरेशिया, बनाते हैं, और यूराल पर्वत को उनके बीच की रेखा माना जाता है। यूरोप एशिया के पश्चिम में है, जिसके उत्तर में आर्कटिक महासागर और पश्चिम में अटलांटिक है। एशिया अफ़्रीका से लाल सागर और स्वेज़ क्षेत्र द्वारा, और उत्तरी अमेरिका से साइबेरिया और अलास्का के बीच के सँकरे जलडमरूमध्य द्वारा अलग होता है।','l1-geo-ural-europe-asia','original_pattern_matched','NCERT Class VI, Geography -- The Earth: Our Habitat (Major Domains of the Earth).','draft'),
('upsc','Geography','World Regions, Water Bodies & Places','mcq','medium','Ships from the Great Lakes of North America reach the Atlantic Ocean through the','उत्तरी अमेरिका की महान झीलों (Great Lakes) से जहाज़ अटलांटिक महासागर तक किसके रास्ते पहुँचते हैं?','{"craft": "precision"}'::jsonb,'[{"id": "a", "body": "Panama Canal", "body_hi": "पनामा नहर", "isCorrect": false}, {"id": "b", "body": "Mississippi and its tributaries", "body_hi": "मिसिसिपी और उसकी सहायक नदियाँ", "isCorrect": false}, {"id": "c", "body": "Hudson Strait", "body_hi": "हडसन जलडमरूमध्य", "isCorrect": false}, {"id": "d", "body": "St Lawrence Seaway", "body_hi": "सेंट लॉरेंस समुद्री मार्ग (Seaway)", "isCorrect": true}]'::jsonb,2,0.66,'The five Great Lakes, linked by canals such as the Soo and the Welland -- which bypasses Niagara Falls -- connect with the St Lawrence river, whose estuary leads to the Atlantic; together they form a unique commercial waterway deep into the heart of North America. The Panama Canal links the Atlantic and the Pacific, the Mississippi system flows to the Gulf of Mexico, and the Hudson Strait links Hudson Bay with the Atlantic far to the north.','पाँचों महान झीलें, सू और वेलैंड जैसी नहरों से जुड़ी -- वेलैंड नियाग्रा जलप्रपात को बाईपास करती है -- सेंट लॉरेंस नदी से जुड़ती हैं, जिसका ज्वारनदमुख अटलांटिक तक ले जाता है; मिलकर वे उत्तरी अमेरिका के भीतरी भाग तक पहुँचने वाला एक अनूठा व्यापारिक जलमार्ग बनाती हैं। पनामा नहर अटलांटिक और प्रशांत को जोड़ती है, मिसिसिपी तंत्र मैक्सिको की खाड़ी में बहता है, और हडसन जलडमरूमध्य बहुत उत्तर में हडसन खाड़ी को अटलांटिक से जोड़ता है।','l1-geo-great-lakes-st-lawrence-seaway','original_pattern_matched','NCERT Class XII, Geography -- Fundamentals of Human Geography (Transport and Communication).','draft'),
('upsc','Geography','World Regions, Water Bodies & Places','statement_based','medium','Consider the following statements about contours on a topographical map:','स्थलाकृतिक मानचित्र पर समोच्च रेखाओं (contours) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Contours are lines joining places of equal height above mean sea level.", "Closely spaced contours show a steep slope, and widely spaced ones a gentle slope.", "A V-shaped contour pattern pointing towards higher ground shows a spur."], "statements_hi": ["समोच्च रेखाएँ औसत समुद्र तल से समान ऊँचाई वाले स्थानों को जोड़ने वाली रेखाएँ हैं।", "पास-पास की समोच्च रेखाएँ तीव्र ढाल, और दूर-दूर की रेखाएँ मंद ढाल दिखाती हैं।", "ऊँची भूमि की ओर इंगित V-आकार की समोच्च रेखाएँ पर्वत-स्कंध (spur) दिखाती हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "application"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: the spacing of contours shows the steepness of the slope, and their shape shows the landform. Statement 3 is wrong: a V-shaped pattern pointing towards higher ground shows a valley cut by a stream; a spur, a tongue of high land projecting into lower ground, gives V-shaped contours pointing towards lower ground.','कथन 1 और 2 सही हैं: समोच्च रेखाओं के बीच की दूरी ढाल की तीव्रता, और उनका आकार भू-आकृति दिखाता है। कथन 3 गलत है: ऊँची भूमि की ओर इंगित V-आकार का प्रतिरूप किसी धारा द्वारा काटी गई घाटी दिखाता है; पर्वत-स्कंध, यानी निचली भूमि में निकली ऊँची भूमि की जीभ, निचली भूमि की ओर इंगित V-आकार की समोच्च रेखाएँ बनाता है।','l1-geo-contours-slope-valley-spur','original_pattern_matched','NCERT Class XI, Geography -- Practical Work in Geography, Part I (Topographical Maps).','draft'),
('upsc','Geography','World Regions, Water Bodies & Places','statement_based','medium','Consider the following statements about the people of the Amazon basin:','अमेज़न बेसिन के लोगों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["They grow most of their food in small clearings in the forest, where cassava (manioc) is a staple.", "Plots cleared by slash and burn are farmed permanently, for generations.", "The Amazon basin drains parts of Brazil, Peru, Colombia and Argentina."], "statements_hi": ["वे अपना अधिकांश भोजन वन के छोटे साफ़ किए गए भूखंडों में उगाते हैं, जहाँ कसावा (मैनिओक) मुख्य भोजन है।", "काटो और जलाओ (slash and burn) से साफ़ किए गए भूखंडों पर पीढ़ियों तक स्थायी खेती होती है।", "अमेज़न बेसिन ब्राज़ील, पेरू, कोलंबिया और अर्जेंटीना के भागों को अपवाहित करता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: men hunt and fish along the rivers while women look after the crops, and cassava, whose starchy root grows under the ground, is the staple; coffee, maize and cocoa are grown as cash crops. Statement 2 is wrong: in slash-and-burn (shifting) cultivation the forest is cleared and burnt, the ash enriches the soil for a few years, and the plot is then abandoned for a new clearing as fertility falls. Statement 3 is wrong: the basin drains parts of Brazil, Peru, Bolivia, Ecuador, Colombia and a small part of Venezuela; Argentina lies outside it, in the basin of the Parana and the La Plata.','केवल कथन 1 सही है: पुरुष नदियों के किनारे शिकार करते और मछली पकड़ते हैं, जबकि स्त्रियाँ फ़सलों की देखभाल करती हैं, और कसावा, जिसकी स्टार्च वाली जड़ ज़मीन के नीचे उगती है, मुख्य भोजन है; कॉफ़ी, मक्का और कोको नकदी फ़सलों के रूप में उगाए जाते हैं। कथन 2 गलत है: काटो और जलाओ (स्थानांतरी) खेती में वन को काटकर जलाया जाता है, राख कुछ वर्षों तक मिट्टी को उपजाऊ बनाती है, और उर्वरता घटने पर भूखंड छोड़कर नया भूखंड साफ़ किया जाता है। कथन 3 गलत है: बेसिन ब्राज़ील, पेरू, बोलीविया, इक्वाडोर, कोलंबिया और वेनेज़ुएला के एक छोटे भाग को अपवाहित करता है; अर्जेंटीना इसके बाहर, पराना और ला प्लाटा के बेसिन में है।','l1-geo-amazon-cassava-slash-burn','original_pattern_matched','NCERT Class VII, Geography -- Our Environment (Life in the Tropical and Subtropical Region).','draft'),
('upsc','Geography','World Regions, Water Bodies & Places','statement_based','medium','Consider the following statements about the Sahara:','सहारा के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Bedouins and the Tuaregs are nomadic peoples of the Sahara who rear livestock such as camels, goats and sheep.", "The discovery of oil in countries such as Algeria, Libya and Egypt has transformed the desert''s economy.", "People who settle around oases grow date palms."], "statements_hi": ["बद्दू (Bedouin) और तुआरेग सहारा के घुमंतू लोग हैं, जो ऊँट, बकरी और भेड़ जैसे पशु पालते हैं।", "अल्जीरिया, लीबिया और मिस्र जैसे देशों में तेल की खोज ने मरुस्थल की अर्थव्यवस्था बदल दी है।", "मरूद्यानों के आसपास बसने वाले लोग खजूर उगाते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "recall"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. The nomads move with their herds in search of water and pasture, and wear heavy robes as protection against dust storms and hot winds; settled people grow date palms, and crops such as rice, wheat and barley, where there is water. Oil and minerals such as iron, phosphorus, manganese and uranium have brought towns, roads and modern buildings to parts of the desert, changing the traditional way of life.','तीनों कथन सही हैं। घुमंतू लोग पानी और चरागाह की खोज में अपने झुंडों के साथ चलते हैं, और धूल भरी आँधियों तथा गर्म हवाओं से बचने के लिए भारी चोगे पहनते हैं; जहाँ पानी हो, वहाँ बसे लोग खजूर, चावल, गेहूँ और जौ उगाते हैं। तेल तथा लोहा, फ़ॉस्फ़ोरस, मैंगनीज़ और यूरेनियम जैसे खनिजों ने मरुस्थल के कुछ भागों में नगर, सड़कें और आधुनिक इमारतें ला दी हैं, जिससे परंपरागत जीवन-शैली बदल गई है।','l1-geo-sahara-bedouin-tuareg-oil','original_pattern_matched','NCERT Class VII, Geography -- Our Environment (Life in the Deserts).','draft'),
('upsc','Geography','World Regions, Water Bodies & Places','statement_based','medium','Consider the following statements about the continents:','महाद्वीपों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Asia covers about one-third of the total land area of the Earth.", "Australia, the smallest continent, lies entirely in the Northern Hemisphere.", "North America is linked to South America by the narrow Isthmus of Panama."], "statements_hi": ["एशिया पृथ्वी के कुल भू-क्षेत्र के लगभग एक-तिहाई भाग पर फैला है।", "सबसे छोटा महाद्वीप, ऑस्ट्रेलिया, पूरी तरह उत्तरी गोलार्ध में स्थित है।", "उत्तरी अमेरिका दक्षिण अमेरिका से सँकरे पनामा स्थलडमरूमध्य द्वारा जुड़ा है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 3 are correct. Asia, the largest continent, lies in the Eastern Hemisphere, and the Tropic of Cancer passes through it; the Isthmus of Panama, a narrow strip of land, joins the two Americas. Statement 2 is wrong: Australia lies entirely in the Southern Hemisphere; surrounded on all sides by oceans and seas, it is called an island continent.','कथन 1 और 3 सही हैं। सबसे बड़ा महाद्वीप एशिया पूर्वी गोलार्ध में है, और कर्क रेखा इससे होकर गुज़रती है; ज़मीन की एक सँकरी पट्टी, पनामा स्थलडमरूमध्य, दोनों अमेरिकाओं को जोड़ती है। कथन 2 गलत है: ऑस्ट्रेलिया पूरी तरह दक्षिणी गोलार्ध में है; चारों ओर से महासागरों और समुद्रों से घिरा होने के कारण इसे द्वीपीय महाद्वीप कहा जाता है।','l1-geo-continents-asia-australia-panama','original_pattern_matched','NCERT Class VI, Geography -- The Earth: Our Habitat (Major Domains of the Earth).','draft'),
('upsc','Geography','World Regions, Water Bodies & Places','statement_based','medium','Consider the following statements about the oceans:','महासागरों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Indian Ocean is the only ocean named after a country.", "The Atlantic Ocean is S-shaped.", "The Atlantic is the second largest ocean.", "The Pacific Ocean is almost circular in shape."], "statements_hi": ["हिंद महासागर एकमात्र महासागर है जिसका नाम किसी देश के नाम पर है।", "अटलांटिक महासागर S-आकार का है।", "अटलांटिक दूसरा सबसे बड़ा महासागर है।", "प्रशांत महासागर लगभग वृत्ताकार है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "recall"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": false}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": true}]'::jsonb,2,0.66,'All four statements are correct. The Indian Ocean, named after India, is almost triangular, bounded by Asia to the north, Africa to the west and Australia to the east; the S-shaped Atlantic, flanked by the Americas on the west and Europe and Africa on the east, has the most indented coastline, which makes it ideal for natural harbours and ports; and the Pacific, the largest, is almost circular, ringed by Asia, Australia and the Americas.','चारों कथन सही हैं। भारत के नाम पर बना हिंद महासागर लगभग त्रिभुजाकार है, जिसके उत्तर में एशिया, पश्चिम में अफ़्रीका और पूर्व में ऑस्ट्रेलिया है; पश्चिम में दोनों अमेरिकाओं और पूर्व में यूरोप तथा अफ़्रीका से घिरे S-आकार के अटलांटिक की तटरेखा सबसे अधिक कटी-फटी है, जो प्राकृतिक बंदरगाहों और पत्तनों के लिए आदर्श है; और सबसे बड़ा प्रशांत लगभग वृत्ताकार है, जो एशिया, ऑस्ट्रेलिया और दोनों अमेरिकाओं से घिरा है।','l1-geo-oceans-shapes-names','original_pattern_matched','NCERT Class VI, Geography -- The Earth: Our Habitat (Major Domains of the Earth).','draft'),
('upsc','Geography','World Regions, Water Bodies & Places','statement_based','medium','Consider the following statements about the network of latitudes and longitudes:','अक्षांशों और देशांतरों के जाल के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["If parallels of latitude are drawn at one-degree intervals, there are 179 of them, counting the Equator, since the poles are points.", "There are 360 meridians of longitude at one-degree intervals.", "The Prime Meridian (0°) passes through Greenwich, near London.", "Every meridian runs from the North Pole to the South Pole."], "statements_hi": ["यदि अक्षांश रेखाएँ एक-एक अंश के अंतराल पर खींची जाएँ, तो विषुवत रेखा सहित वे 179 होंगी, क्योंकि ध्रुव बिंदु हैं।", "एक-एक अंश के अंतराल पर देशांतर की 360 याम्योत्तर रेखाएँ हैं।", "प्रधान याम्योत्तर (0°) लंदन के पास ग्रीनविच से होकर गुज़रती है।", "हर याम्योत्तर रेखा उत्तरी ध्रुव से दक्षिणी ध्रुव तक जाती है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": false}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": true}]'::jsonb,2,0.66,'All four statements are correct. With 89 parallels in each hemisphere and the Equator, there are 179 parallels; the poles, at 90 degrees, are points. Meridians, unlike parallels, are all of equal length, and each is a semicircle joining the poles; the Prime Meridian through the Royal Observatory at Greenwich divides the Earth into the Eastern and Western Hemispheres, and longitudes are counted up to 180 degrees east and west of it.','चारों कथन सही हैं। हर गोलार्ध में 89 अक्षांश रेखाओं और विषुवत रेखा को मिलाकर 179 रेखाएँ होती हैं; 90 अंश पर स्थित ध्रुव बिंदु हैं। याम्योत्तर रेखाएँ, अक्षांश रेखाओं के विपरीत, सभी समान लंबाई की होती हैं, और हर एक ध्रुवों को जोड़ने वाला अर्धवृत्त है; ग्रीनविच की रॉयल वेधशाला से होकर जाने वाली प्रधान याम्योत्तर पृथ्वी को पूर्वी और पश्चिमी गोलार्धों में बाँटती है, और देशांतर उसके पूर्व और पश्चिम में 180 अंश तक गिने जाते हैं।','l1-geo-parallels-179-meridians-360','original_pattern_matched','NCERT Class VI, Geography -- The Earth: Our Habitat (Globe: Latitudes and Longitudes).','draft'),
('upsc','Geography','World Regions, Water Bodies & Places','assertion_reason','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "The Amazon basin receives heavy rainfall almost every day.", "assertion_hi": "अमेज़न बेसिन में लगभग हर दिन भारी वर्षा होती है।", "reason": "It lies close to the Equator, where hot, humid air rises and forms clouds, bringing rain, often in the afternoon.", "reason_hi": "यह विषुवत रेखा के निकट स्थित है, जहाँ गर्म, नम हवा ऊपर उठकर बादल बनाती है और वर्षा लाती है, प्रायः दोपहर में।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true, "craft": "inference"}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": true}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct, and Statement-II explains Statement-I. The equatorial region is hot and wet throughout the year, and the strong heating of the moist air every day produces convectional rain, often in heavy afternoon showers. The constant warmth and moisture support the thick rainforest, whose canopy is so dense that little sunlight reaches the forest floor.','दोनों कथन सही हैं, और कथन-II कथन-I की व्याख्या करता है। विषुवतीय क्षेत्र वर्ष भर गर्म और नम रहता है, और नम हवा का रोज़ तेज़ गर्म होना संवहनी वर्षा लाता है, प्रायः दोपहर की भारी बौछारों में। निरंतर गर्मी और नमी घने वर्षा वन को पोषित करती है, जिसका वितान इतना घना है कि वन के तल तक बहुत कम धूप पहुँचती है।','l1-geo-amazon-daily-rain-equator','original_pattern_matched','NCERT Class VII, Geography -- Our Environment (Life in the Tropical and Subtropical Region).','draft'),
('upsc','Geography','World Regions, Water Bodies & Places','assertion_reason','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "Antarctica lies entirely in the Southern Hemisphere.", "assertion_hi": "अंटार्कटिका पूरी तरह दक्षिणी गोलार्ध में स्थित है।", "reason": "It has a large permanent population living in towns.", "reason_hi": "वहाँ नगरों में रहने वाली बड़ी स्थायी जनसंख्या है।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": false}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": true}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Statement-I is correct but Statement-II is incorrect. Antarctica, surrounding the South Pole, is permanently covered by thick ice sheets and has no permanent human settlements; many countries, India among them, maintain research stations there, staffed by scientists in turns.','कथन-I सही है, पर कथन-II गलत है। दक्षिणी ध्रुव के चारों ओर फैला अंटार्कटिका स्थायी रूप से मोटी हिम-चादरों से ढका है और वहाँ कोई स्थायी मानव बस्ती नहीं है; भारत सहित कई देश वहाँ अनुसंधान केंद्र चलाते हैं, जिनमें वैज्ञानिक बारी-बारी से रहते हैं।','l1-geo-antarctica-southern-no-settlements','original_pattern_matched','NCERT Class VI, Geography -- The Earth: Our Habitat (Major Domains of the Earth).','draft'),
('upsc','Geography','World Regions, Water Bodies & Places','match_the_following','medium','Consider the following pairs of India''s polar research stations and their locations:','भारत के ध्रुवीय अनुसंधान केंद्रों और उनके स्थानों के निम्नलिखित युग्मों पर विचार कीजिए:','{"list_1": ["1. Dakshin Gangotri", "2. Maitri", "3. Bharati", "4. Himadri"], "list_1_hi": ["1. दक्षिण गंगोत्री", "2. मैत्री", "3. भारती", "4. हिमाद्रि"], "list_2": ["India''s first scientific base in Antarctica, set up in 1983", "Station in the Schirmacher Oasis of Antarctica", "Station in the Larsemann Hills of Antarctica", "Station on the Antarctic Peninsula"], "list_2_hi": ["अंटार्कटिका में भारत का पहला वैज्ञानिक केंद्र, 1983 में स्थापित", "अंटार्कटिका के शिरमाखर मरूद्यान में स्थित केंद्र", "अंटार्कटिका की लार्समैन पहाड़ियों में स्थित केंद्र", "अंटार्कटिक प्रायद्वीप पर स्थित केंद्र"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": true}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": false}]'::jsonb,2,0.66,'Pairs 1, 2 and 3 are correctly matched. Dakshin Gangotri, set up during the third Indian expedition, was later buried under ice and used as a supply base; Maitri (1989) and Bharati (2012) are India''s active Antarctic stations. Pair 4 is wrong: Himadri (2008) is India''s research station in the Arctic, at Ny-Alesund in the Svalbard archipelago; the stations are run under the National Centre for Polar and Ocean Research, Goa.','युग्म 1, 2 और 3 सही सुमेलित हैं। तीसरे भारतीय अभियान के दौरान स्थापित दक्षिण गंगोत्री बाद में बर्फ़ में दब गया और आपूर्ति केंद्र के रूप में प्रयुक्त हुआ; मैत्री (1989) और भारती (2012) अंटार्कटिका में भारत के सक्रिय केंद्र हैं। युग्म 4 गलत है: हिमाद्रि (2008) आर्कटिक में, स्वालबार्ड द्वीपसमूह के नी-ऑलेसुंड में भारत का अनुसंधान केंद्र है; ये केंद्र राष्ट्रीय ध्रुवीय एवं समुद्री अनुसंधान केंद्र, गोवा के अधीन चलते हैं।','l1-geo-india-polar-stations-pairs','original_pattern_matched','National Centre for Polar and Ocean Research, Ministry of Earth Sciences; NCERT Class VI, Geography -- The Earth: Our Habitat.','draft'),
('upsc','Geography','World Regions, Water Bodies & Places','mcq','hard','On a topographical sheet with a representative fraction of 1:50,000, a road measures 6 cm. What is its length on the ground?','1:50,000 निरूपक भिन्न (representative fraction) वाली स्थलाकृतिक शीट पर एक सड़क 6 सेमी मापी जाती है। ज़मीन पर उसकी लंबाई क्या है?','{"craft": "application"}'::jsonb,'[{"id": "a", "body": "30 km", "body_hi": "30 किमी", "isCorrect": false}, {"id": "b", "body": "300 m", "body_hi": "300 मीटर", "isCorrect": false}, {"id": "c", "body": "12 km", "body_hi": "12 किमी", "isCorrect": false}, {"id": "d", "body": "3 km", "body_hi": "3 किमी", "isCorrect": true}]'::jsonb,2,0.66,'A representative fraction of 1:50,000 means that one unit on the map stands for 50,000 of the same units on the ground: 1 cm = 50,000 cm = 500 m = 0.5 km. So 6 cm on the map represents 6 x 0.5 = 3 km. Because a representative fraction has no units, it can be read in any unit of measurement, which makes it the most widely used way of stating the scale of topographical sheets.','1:50,000 निरूपक भिन्न का अर्थ है कि मानचित्र पर एक इकाई ज़मीन पर उसी इकाई की 50,000 इकाइयों के बराबर है: 1 सेमी = 50,000 सेमी = 500 मीटर = 0.5 किमी। इसलिए मानचित्र पर 6 सेमी ज़मीन पर 6 x 0.5 = 3 किमी दर्शाता है। चूँकि निरूपक भिन्न की कोई इकाई नहीं होती, उसे किसी भी माप-इकाई में पढ़ा जा सकता है, इसीलिए स्थलाकृतिक शीटों का पैमाना बताने का यह सबसे प्रचलित तरीक़ा है।','l1-geo-representative-fraction-calculation','original_pattern_matched','NCERT Class XI, Geography -- Practical Work in Geography, Part I (Map Scale).','draft'),
('upsc','Geography','World Regions, Water Bodies & Places','statement_based','hard','Consider the following statements about the length of a degree of latitude and longitude:','अक्षांश और देशांतर के एक अंश की लंबाई के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["One degree of latitude measures roughly 111 km everywhere on the Earth.", "One degree of longitude measures about 111 km at the Equator and shrinks to zero at the poles.", "At 60° latitude, one degree of longitude measures about a quarter of its length at the Equator."], "statements_hi": ["पृथ्वी पर हर जगह अक्षांश का एक अंश लगभग 111 किमी होता है।", "देशांतर का एक अंश विषुवत रेखा पर लगभग 111 किमी होता है और ध्रुवों पर घटकर शून्य हो जाता है।", "60° अक्षांश पर देशांतर का एक अंश विषुवत रेखा पर अपनी लंबाई का लगभग एक-चौथाई होता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "application"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: parallels are equally spaced, so a degree of latitude is nearly constant, but meridians converge towards the poles, so the distance between them along a parallel shrinks. Statement 3 is wrong: the length of a degree of longitude varies with the cosine of the latitude, and since the cosine of 60 degrees is one-half, a degree of longitude there is about half its equatorial length -- some 55-56 km.','कथन 1 और 2 सही हैं: अक्षांश रेखाएँ समान दूरी पर हैं, इसलिए अक्षांश का एक अंश लगभग स्थिर रहता है, पर याम्योत्तर रेखाएँ ध्रुवों की ओर मिलती जाती हैं, इसलिए किसी अक्षांश रेखा पर उनके बीच की दूरी घटती जाती है। कथन 3 गलत है: देशांतर के एक अंश की लंबाई अक्षांश के कोसाइन के अनुसार बदलती है, और 60 अंश का कोसाइन आधा है, इसलिए वहाँ देशांतर का एक अंश विषुवतीय लंबाई का लगभग आधा -- लगभग 55-56 किमी -- होता है।','l1-geo-degree-length-cosine-60','original_pattern_matched','NCERT Class XI, Geography -- Practical Work in Geography, Part I (Latitude, Longitude and Time).','draft'),
('upsc','Geography','World Regions, Water Bodies & Places','statement_based','hard','Consider the following statements about the Mercator projection:','मर्केटर प्रक्षेप (Mercator projection) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It shows the shapes of small areas correctly, but greatly exaggerates the size of areas in high latitudes.", "On it, Greenland appears about as large as South America, though it is much smaller.", "Because a straight line on it keeps a constant compass bearing, it is used for navigation charts."], "statements_hi": ["यह छोटे क्षेत्रों का आकार सही दिखाता है, पर उच्च अक्षांशों के क्षेत्रों का आकार बहुत बढ़ा-चढ़ाकर दिखाता है।", "इस पर ग्रीनलैंड लगभग दक्षिण अमेरिका जितना बड़ा दिखता है, यद्यपि वह उससे बहुत छोटा है।", "चूँकि इस पर सीधी रेखा एक स्थिर दिक्सूचक दिशा बनाए रखती है, इसलिए इसका उपयोग नौवहन चार्टों के लिए होता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "inference"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. The Mercator projection is conformal -- it keeps shapes and directions correct locally -- but to do so it stretches the scale more and more towards the poles, which it cannot show at all; so Greenland, about one-eighth the size of South America, looks as large. Its straight lines are lines of constant bearing (loxodromes), which is why sailors have long used it, though the shortest route between two places is a great circle, not a straight line on this map.','तीनों कथन सही हैं। मर्केटर प्रक्षेप शुद्ध-आकृतिक (conformal) है -- यह स्थानीय रूप से आकार और दिशाएँ सही रखता है -- पर इसके लिए यह ध्रुवों की ओर पैमाने को बढ़ाता जाता है, और ध्रुवों को बिल्कुल नहीं दिखा सकता; इसलिए दक्षिण अमेरिका के लगभग आठवें भाग जितना ग्रीनलैंड उतना ही बड़ा दिखता है। इसकी सीधी रेखाएँ स्थिर दिशा की रेखाएँ (loxodrome) हैं, इसीलिए नाविक लंबे समय से इसका उपयोग करते आए हैं, यद्यपि दो स्थानों के बीच सबसे छोटा मार्ग इस मानचित्र पर सीधी रेखा नहीं, बल्कि बृहत् वृत्त होता है।','l1-geo-mercator-projection','original_pattern_matched','NCERT Class XI, Geography -- Practical Work in Geography, Part I (Map Projections).','draft'),
('upsc','Geography','World Regions, Water Bodies & Places','assertion_reason','hard','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "At the Equator, day and night are of nearly equal length throughout the year.", "assertion_hi": "विषुवत रेखा पर वर्ष भर दिन और रात लगभग बराबर होते हैं।", "reason": "The Earth''s axis is inclined at an angle of 66½° to the plane of its orbit.", "reason_hi": "पृथ्वी का अक्ष उसके कक्षा-तल से 66½° का कोण बनाता है।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true, "craft": "inference"}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": false}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": true}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct, but Statement-II is not the correct explanation for Statement-I. The circle of illumination, which divides day from night, always bisects the Equator, whatever the season, so day and night there stay close to twelve hours each. The tilt of the axis explains why the length of day and night changes through the year everywhere else, and why there are seasons -- not why the Equator is the exception.','दोनों कथन सही हैं, पर कथन-II कथन-I की सही व्याख्या नहीं है। दिन को रात से अलग करने वाला प्रदीप्ति वृत्त, ऋतु कोई भी हो, विषुवत रेखा को सदा दो बराबर भागों में बाँटता है, इसलिए वहाँ दिन और रात लगभग बारह-बारह घंटे के रहते हैं। अक्ष का झुकाव बताता है कि बाक़ी सब जगह दिन और रात की लंबाई वर्ष भर क्यों बदलती है, और ऋतुएँ क्यों होती हैं -- यह नहीं कि विषुवत रेखा अपवाद क्यों है।','l1-geo-equator-equal-days-tilt','original_pattern_matched','NCERT Class VI, Geography -- The Earth: Our Habitat (Motions of the Earth).','draft')
